SELECT id, doc_id, version_id, changed_at, before_effective_from, before_until_kind, before_effective_until,
    after_effective_from, after_until_kind, after_effective_until, visible_to_readers, reason
FROM kb_document_applicability_change WHERE doc_id = #{documentId} AND version_id = #{versionId}
AND (changed_at, id) < (#{beforeTime}, #{beforeId})
ORDER BY changed_at DESC, id DESC LIMIT #{limit}

